import{_ as e,o as t,c as r,ae as o}from"./chunks/framework.D2MaNxof.js";const _=JSON.parse('{"title":"学习方式","description":"","frontmatter":{},"headers":[],"relativePath":"learning-method.md","filePath":"learning-method.md"}'),n={name:"learning-method.md"};function i(l,a,h,d,p,s){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="学习方式" tabindex="-1">学习方式 <a class="header-anchor" href="#学习方式" aria-label="Permalink to &quot;学习方式&quot;">​</a></h1><p>每篇围绕一个明确的能力增量。先看具体问题与运行过程，再把过程对应到代码，最后通过实际运行、断点和故障实验检查理解。</p><h2 id="先知道自己在建设哪里" tabindex="-1">先知道自己在建设哪里 <a class="header-anchor" href="#先知道自己在建设哪里" aria-label="Permalink to &quot;先知道自己在建设哪里&quot;">​</a></h2><p>章节开头说明当前阶段、本章新增行为，以及它服务的阶段成果。系统图突出当前部分，区分已经实现与后续内容；具体轨迹图展示请求、实际返回与下一步使用的数据。</p><h2 id="分步实现-完整文件核对" tabindex="-1">分步实现，完整文件核对 <a class="header-anchor" href="#分步实现-完整文件核对" aria-label="Permalink to &quot;分步实现，完整文件核对&quot;">​</a></h2><p>每步明确文件、位置和完整逻辑块，关键边界有中文意图注释。代码附近解释谁调用、谁执行、谁保存、下一步谁使用。章末完整文件与前文同源，用于核对，不代替讲解。</p><p>首次出现的术语先用普通语言解释，再连接当前任务。配套材料会提供完整创建步骤；其业务逻辑按理解任务所需说明，重点仍是 Agent 与运行系统的行为。</p><h2 id="用行为检查理解" tabindex="-1">用行为检查理解 <a class="header-anchor" href="#用行为检查理解" aria-label="Permalink to &quot;用行为检查理解&quot;">​</a></h2><p>运行之前先预测结果；运行后对照具体日志、变量或哪一轮行为。修改实验后恢复材料，再换任务复用。工具执行成功、模型停止与任务完成分别判断。</p><p>固定响应便于复现程序路径，会明确标注；它不能证明真实模型一定会自主选择同样的动作。类型检查和构建通过也不代表任务质量或已经掌握。</p><h2 id="工程怎样累积" tabindex="-1">工程怎样累积 <a class="header-anchor" href="#工程怎样累积" aria-label="Permalink to &quot;工程怎样累积&quot;">​</a></h2><p>核心通过公开包接口供应用使用，任务示例不反向进入核心。后续持续演进同一套实现，并在阶段节点检查依赖、状态归属、失败处理与任务质量。</p><p>网站由项目预先准备，不占 Agent 章节的教学篇幅。实际运行模型的配置与调用由操作者管理，密钥不写入页面或版本库。</p>',13)])])}const m=e(n,[["render",i]]);export{_ as __pageData,m as default};
